    ((select id from sermons where service_date = '2026-08-16' and title = 'Altars and the Believer''s Victory'), 1, 'Jesus disarmed the spiritual rulers and shamed them publicly - you are not fighting for victory, you are enforcing one already won', 'victory already won', '01:47:04 - 01:49:10 (service) / approx 02:20 - 04:30 (sermon MP4)', '{instagram,facebook,tiktok,youtube}', 'rendered', false, null),
    ((select id from sermons where service_date = '2026-08-16' and title = 'Altars and the Believer''s Victory'), 2, 'Overwhelming victory is ours through Christ Jesus - no matter what the enemy throws', 'overwhelming victory', '01:49:12 - 01:50:21 (service) / approx 04:30 - 05:40 (sermon MP4)', '{instagram,facebook,tiktok,youtube}', 'rendered', false, null),
    ((select id from sermons where service_date = '2026-08-16' and title = 'Altars and the Believer''s Victory'), 3, 'Faith is not denial - gravity never stops pulling, but lift is the higher force', 'faith vs reality', '01:59:17 - 02:02:35 (service) / approx 14:35 - 17:55 (sermon MP4)', '{instagram,facebook,tiktok,youtube}', 'candidate', false, null),
    ((select id from sermons where service_date = '2026-08-16' and title = 'Altars and the Believer''s Victory'), 4, 'Whatsoever you do not resist, you are permitting - the flu that would not leave', 'testimony: resisting', '02:19:52 - 02:24:20 (service) / approx 35:10 - 39:40 (sermon MP4)', '{instagram,facebook,tiktok,youtube}', 'candidate', true, 'Personal health testimony. She tells it herself and publicly, but it names an illness and a period of lost income - confirm with her before it is cut as a standalone clip.'),
